//This detects the setting of registry keys specific to disabling important security and admin tools.
//Attackers may do this to evade detection.
let eventtype = dynamic(["RegistryValueSet"]);
let RegistryValueData = dynamic(["DWORD (0x00000000)"]);
let RegistryValue = dynamic(["StartMenuLogOff","DisableChangePassword","DisableLockWorkstation","DisableRegistryTools","DisableTaskmgr","NoDispBackgroundPage","NoDispCPL","DisableNotificationCenter","DisableCMD","ConsentPromptBehaviorAdmin","shutdownwithoutlogon","Write Protection","WriteProtect","ToastEnabled"]);
_Im_RegistryEvent(eventtype_in=eventtype,registryvalue_has_any=RegistryValue,registrydata_has_any=RegistryValueData)
| extend
    Computer = tostring(column_ifexists("DvcHostname", "")),
    Account = tostring(column_ifexists("ActorUsername", "")),
    CommandLine = tostring(column_ifexists("ActingProcessCommandLine", "")),
    ProcessId = tostring(column_ifexists("ActingProcessId", ""))
